import{_ as a,a as t}from"./chunks/lifecycle-diagram.DqhRXCS3.js";import{_ as i,o as r,c as o,a0 as d}from"./chunks/framework.tsJrOMu2.js";const b=JSON.parse('{"title":"架构总览","description":"","frontmatter":{},"headers":[],"relativePath":"zh/architecture/README.md","filePath":"zh/architecture/README.md"}'),l={name:"zh/architecture/README.md"};function c(n,e,p,s,h,g){return r(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h1><p>Agentrail 采用分层结构组织。理解各层职责，有助于判断代码应放在哪里，以及如何在不与框架结构冲突的前提下扩展能力。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><p><img src="'+a+'" alt="Agentrail 架构图：从上到下依次为业务应用、 与 、以及基础层 。"></p><p>这个结构由两个维度决定：</p><ul><li>纵向维度「依赖方向」：每一层只依赖下层，不反向依赖。关系为 <code>core ← capabilities ← app</code>。</li><li>横向维度「组合方式」：<code>@agentrail/app</code> 不只是更高一层，也负责把 <code>@agentrail/capabilities</code> 与 <code>@agentrail/core</code> 组合成完整的托管请求生命周期。</li></ul><h2 id="分层说明" tabindex="-1">分层说明 <a class="header-anchor" href="#分层说明" aria-label="Permalink to &quot;分层说明&quot;">​</a></h2><h3 id="_1-agentrail-core" tabindex="-1">1. <code>@agentrail/core</code> <a class="header-anchor" href="#_1-agentrail-core" aria-label="Permalink to &quot;1. `@agentrail/core`&quot;">​</a></h3><p>这是执行层基础。定义 Agent、工具契约 <code>defineTool</code>、LLM Provider 抽象、Agent Loop、消息类型、Prompt SDK、Session 类型契约与用量统计。</p><p>这一层不关心 HTTP、Session 存储或 Host 生命周期。</p><h3 id="_2-agentrail-capabilities" tabindex="-1">2. <code>@agentrail/capabilities</code> <a class="header-anchor" href="#_2-agentrail-capabilities" aria-label="Permalink to &quot;2. `@agentrail/capabilities`&quot;">​</a></h3><p>这是可复用能力层，用于扩展 Agent 的可操作范围。当前包含：</p><ul><li>基于 Docker 的文件系统与浏览器工具</li><li>知识库索引与检索</li><li>技能发现与执行</li><li>多 Agent 编排</li><li>通用工具，如 Web 搜索、提问、待办写入</li></ul><p>这些能力可以通过 <code>defineProfile({ capabilities: [...] })</code> 注入到 Profile 中。</p><h3 id="_3-agentrail-app" tabindex="-1">3. <code>@agentrail/app</code> <a class="header-anchor" href="#_3-agentrail-app" aria-label="Permalink to &quot;3. `@agentrail/app`&quot;">​</a></h3><p>这是推荐的服务端接入层，负责：</p><ul><li>通过 <code>createAgentApp</code> 提供 <code>/chat</code> 与 <code>/stream</code></li><li>通过 <code>defineProfile</code> 定义 Profile</li><li>Session 管理</li><li>插件与 Slash Command 扩展模型</li><li>类型化配置加载</li><li>SSE 事件契约</li></ul><p>对于托管场景，通常从这一层开始。</p><h3 id="_4-业务应用" tabindex="-1">4. 业务应用 <a class="header-anchor" href="#_4-业务应用" aria-label="Permalink to &quot;4. 业务应用&quot;">​</a></h3><p>这一层是业务代码本身，包括 Profile、路由、UI 与业务逻辑。它依赖框架，但不属于框架的一部分。</p><h2 id="包一览" tabindex="-1">包一览 <a class="header-anchor" href="#包一览" aria-label="Permalink to &quot;包一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>层级</th><th>用途</th></tr></thead><tbody><tr><td><code>@agentrail/core</code></td><td>1</td><td>Agent Loop、工具契约、LLM Providers、Prompt、Session 类型</td></tr><tr><td><code>@agentrail/capabilities</code></td><td>2</td><td>Sandbox、知识库、技能、编排、内置工具</td></tr><tr><td><code>@agentrail/app</code></td><td>3</td><td><code>createAgentApp</code>、<code>defineProfile</code>、Session、插件、配置</td></tr><tr><td><code>@agentrail/cli</code></td><td>工具</td><td>本地诊断与配置检查</td></tr><tr><td><code>@agentrail/testing</code></td><td>工具</td><td>运行时与托管层测试辅助</td></tr><tr><td><code>@agentrail/deep-research</code></td><td>附加包</td><td>多 Agent 深度研究工作流</td></tr><tr><td><code>@agentrail/create-agentrail-app</code></td><td>工具</td><td>项目脚手架</td></tr></tbody></table><h2 id="请求生命周期" tabindex="-1">请求生命周期 <a class="header-anchor" href="#请求生命周期" aria-label="Permalink to &quot;请求生命周期&quot;">​</a></h2><p>当消息进入流式接口时，流程大致如下：</p><p><img src="'+t+'" alt="Agentrail 请求生命周期：从  开始，经过 Session、Profile、历史记录、压缩、上下文组装、Agent 执行、持久化与结束。"></p><p><code>/chat</code> 与 <code>/stream</code> 走的是同一套核心流程，区别在于前者返回聚合后的 JSON，后者按事件流式返回。</p><h2 id="推荐入口与低层入口" tabindex="-1">推荐入口与低层入口 <a class="header-anchor" href="#推荐入口与低层入口" aria-label="Permalink to &quot;推荐入口与低层入口&quot;">​</a></h2><p>Agentrail 明确区分「推荐入口」与「低层入口」。</p><p>推荐入口：</p><ul><li><code>createAgentApp({ dataDir, profiles, ... })</code></li><li><code>defineProfile(definition)</code></li></ul><p>低层入口：</p><ul><li><code>createChatRoute(...)</code></li><li><code>createStreamRoute(...)</code></li><li><code>createOrchestrationRegistry(...)</code></li></ul><p>对于新项目，优先从 <code>createAgentApp</code> + <code>defineProfile</code> 开始。它们不是黑盒，而是一组已经组装好的推荐组合。随着应用复杂度上升，可以逐步拆开并替换其中的组件。</p><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><p>建议按以下顺序阅读：</p><ol><li><a href="./../guides/quickstart">快速开始</a></li><li><a href="./../concepts/agents">Agent</a></li><li><a href="./../concepts/tools">工具</a></li><li><a href="./../guides/build-a-profile">构建 Profile</a></li><li><a href="./../reference/create-agent-app"><code>createAgentApp</code> 参考</a></li><li><a href="/examples/playground-server">Playground Server 示例（英文）</a></li></ol>',36)])])}const m=i(l,[["render",c]]);export{b as __pageData,m as default};
